module logic;
use model {Summary};
use util {reverse};
record ParseState {pos:I64,frames:List<Bytes>,consumed:I64,error:I64}
fn run(data:Bytes,limit:I64)->Summary {
 let final=fold(i in Bytes::length(data),state:ParseState=ParseState {pos:0,frames:List::empty<Bytes>(),consumed:0,error:0}) {
  if state.error!=0 || state.pos>=Bytes::length(data) {state} else {
   let n=Bytes::at(data,state.pos);
   if n>limit {ParseState {pos:state.pos,frames:state.frames,consumed:state.pos,error:3}} else {
    if Bytes::length(data)-state.pos<n+2 {ParseState {pos:state.pos,frames:state.frames,consumed:state.pos,error:1}} else {
     let payload=Bytes::slice(data,state.pos+1,n);
     let sum=fold(j in n,total:I64=0) {total+Bytes::at(payload,j)};
     if sum%256!=Bytes::at(data,state.pos+1+n) {ParseState {pos:state.pos,frames:state.frames,consumed:state.pos,error:2}} else {
      ParseState {pos:state.pos+n+2,frames:List::prepend(payload,state.frames),consumed:state.pos+n+2,error:0}
     }
    }
   }
  }
 };
 Summary {frames:reverse(final.frames),consumed:final.consumed,error:final.error}
}
